"""Embedded brand assets for the fraud dashboard.

The OpenG2P logo is inlined as a base64 data URI (rather than a file COPYd
into the image) so it survives container rebuilds and needs no static-file
server — the dashboard image is rebuilt from source, not bind-mounted.
"""

OPENG2P_LOGO_B64 = ""

OPENG2P_ICON_B64 = ""

OPENG2P_LOGO_URI = f"data:image/png;base64,{OPENG2P_LOGO_B64}"
OPENG2P_ICON_URI = f"data:image/png;base64,{OPENG2P_ICON_B64}"
